insert into public.issues (id, district_id, title, description, category, status, lat, lng, location_label, location_detail, via, owner, agency, merged_into, fixed_at, created_at) values
  ('PP-2402', 'west-side-demo', 'Two streetlights out on W 16th St', 'Lamp posts L-11 and L-12 between 9th and 10th Ave have been dark for weeks. The block is pitch black after 7pm.', 'lighting', 'sent_to_city', 40.742509999999996, -74.0059, 'W 16th St', 'Lamp posts L-11 and L-12', 'QR · BID noticeboard Q-12', 'NYC DOT', 'NYC DOT', null, null, private.seed_ago(16)),
  ('PP-2419', 'west-side-demo', 'Loose paver trips people at W 15th St', 'A raised paver on the corner has tripped at least two people this week. Hard to see at night.', 'accessibility', 'scheduled', 40.74265, -74.00765, '10th Ave & W 15th', null, 'Map · problempins.org', 'BID crew', null, null, null, private.seed_ago(11)),
  ('PP-2431', 'west-side-demo', 'Bench missing slats by Chelsea Market', 'Two slats are gone from the bench outside the 9th Ave entrance. Exposed bolts.', 'seating', 'in_review', 40.741611999999996, -74.00496, 'Chelsea Market', null, 'Map · problempins.org', 'BID crew', null, null, null, private.seed_ago(21)),
  ('PP-2440', 'west-side-demo', 'Leaf blowers before 7am on W 14th St', 'Landscaping crews start running leaf blowers around 6am most weekdays.', 'noise', 'open', 40.74151, -74.007, 'W 14th St', null, 'Map · problempins.org', null, 'NYC DEP', null, null, private.seed_ago(6)),
  ('PP-2447', 'west-side-demo', 'Bins overflowing at 9th Ave & W 18th', 'Both corner bins are full by noon on weekends and trash blows into the street.', 'litter', 'scheduled', 40.742917999999996, -74.00369, '9th Ave & W 18th', null, 'Map · problempins.org', 'BID crew', null, null, null, private.seed_ago(4)),
  ('PP-2388', 'west-side-demo', 'No shaded seating on W 15th St plaza', 'The plaza gets full sun all afternoon and there is nowhere to sit in the shade.', 'seating', 'open', 40.741668000000004, -74.00566, 'Chelsea Market', null, 'Map · problempins.org', null, null, null, null, private.seed_ago(34)),
  ('PP-2451', 'west-side-demo', 'Graffiti on W 17th St scaffolding', 'Fresh tags all along the scaffolding shed on the north side of the street.', 'other', 'open', 40.74341, -74.0061, 'W 17th St', null, 'Map · problempins.org', null, null, null, null, private.seed_ago(2)),
  ('PP-2393', 'west-side-demo', 'Flickering light at W 18th St garage exit', 'The light over the garage exit strobes on and off, hard to see pedestrians.', 'lighting', 'scheduled', 40.74415, -74.006, 'W 18th St', null, 'Map · problempins.org', 'BID crew', null, null, null, private.seed_ago(25)),
  ('PP-2455', 'west-side-demo', 'Planter knocked over at 10th Ave & W 16th', 'One of the big planters is on its side and blocking half the sidewalk.', 'other', 'open', 40.743261999999994, -74.00731, '10th Ave & W 16th', null, 'Map · problempins.org', null, null, null, null, private.seed_ago(1)),
  ('PP-2449', 'west-side-demo', 'Bike rack bent outside the library', 'The rack outside the Muhlenberg library is bent flat and unusable.', 'other', 'in_review', 40.741758, -74.00211, 'W 23rd St library', null, 'Map · problempins.org', 'West Side District staff', null, null, null, private.seed_ago(3)),
  ('PP-2458', 'west-side-demo', 'Sidewalk café blocks curb cut on 9th Ave', 'A sandwich board blocks the curb cut every morning, about 7 to 11. Had to roll into the street to get around it.', 'accessibility', 'open', 40.743249999999996, -74.00342, '9th Ave & W 18th', null, 'Map · problempins.org', null, null, null, null, private.seed_ago(1)),
  ('PP-2297', 'west-side-demo', 'Tree roots lifting sidewalk, W 19th St', 'Roots have pushed up a slab about two inches. Strollers and wheelchairs catch on it.', 'accessibility', 'sent_to_city', 40.744249999999994, -74.0047, 'W 19th St', null, 'Map · problempins.org', 'NYC Parks', 'NYC Parks', null, null, private.seed_ago(63)),
  ('PP-2310', 'west-side-demo', 'Crosswalk signal stuck at 9th Ave & W 18th', 'The walk signal never changes for the east crosswalk. People cross against the light.', 'accessibility', 'sent_to_city', 40.742684000000004, -74.0034, '9th Ave & W 18th', null, 'Map · problempins.org', 'NYC DOT', 'NYC DOT', null, null, private.seed_ago(46)),
  ('PP-2371', 'west-side-demo', 'Broken bench by the fountain', 'The bench by the plaza fountain was split down the middle.', 'seating', 'fixed', 40.74459, -74.00385000000001, 'W 20th St plaza', null, 'Map · problempins.org', 'BID crew', null, null, private.seed_ago(25, 1), private.seed_ago(40)),
  ('PP-2362', 'west-side-demo', 'Overflowing bins on W 20th St', 'Bins at the corner of W 20th and 10th Ave overflowing every weekend.', 'litter', 'fixed', 40.74555, -74.00565, 'W 20th St & 10th Ave', null, 'Map · problempins.org', 'BID crew', null, null, private.seed_ago(40, 1), private.seed_ago(43)),
  ('PP-2459', 'west-side-demo', 'Dog waste in W 19th St tree pits', 'Tree pits along the south side are full of dog waste.', 'litter', 'open', 40.743689999999994, -74.00365000000001, 'W 19th St', null, 'Map · problempins.org', null, null, null, null, private.seed_ago(1));
