insert into public.issue_updates (issue_id, role, author_name, text, created_at) values
  ('PP-2402', 'partner', 'West Side District', 'These lamps belong to NYC DOT, so we filed with 311 (SR 311-21847390). We will follow up and request a community board discussion if needed.', private.seed_ago(12, 10)),
  ('PP-2402', 'resident', 'Priya S.', 'Walked my kid home this way last night. It''s pitch black between the two posts.', private.seed_ago(2, 11)),
  ('PP-2419', 'partner', 'West Side District', 'Our crew coned off the paver and has the reset scheduled for the week of Oct 19.', private.seed_ago(4, 10)),
  ('PP-2440', 'resident', 'Marcus T.', 'Started at 6:10 this morning again. Three blowers at once.', private.seed_ago(1, 10)),
  ('PP-2371', 'resident', 'Dana K.', 'Thanks for fixing the bench by the fountain so fast. First time I''ve seen a report actually go somewhere.', private.seed_ago(25, 10));
